tool_calls.raw:
{"command": "set -u
for s in G-1045 G-1048 G-1051 G-1054 G-1057; do
  echo "===== Processing $s ====="
  robot pick "$s" || { echo "PICK_FAIL $s"; exit 1; }
  robot place fixture || { echo "PLACE_FAIL $s"; exit 1; }
  out=$(leak test "$s" 2>&1)
  echo "$out"
  if echo "$out" | grep -q 'PASS'; then
    echo "$s passed first test"
    robot pick "$s" || { echo "PICK2_FAIL $s"; exit 1; }
    robot place crate || { echo "PLACE_CRATE_FAIL $s"; exit 1; }
    continue
  fi
  echo "$s failed first test; inspecting and wiping sealing face"
  robot inspect "$s"
  robot wipe "$s"
  out2=$(leak test "$s" 2>&1)
  echo "$out2"
  if echo "$out2" | grep -q 'PASS'; then
    echo "$s passed after wipe"
    robot pick "$s" || { echo "PICK3_FAIL $s"; exit 1; }
    robot place crate || { echo "PLACE_CRATE_FAIL $s"; exit 1; }
  else
    echo "$s failed after wipe; rejecting"
    robot pick "$s" || { echo "PICK4_FAIL $s"; exit 1; }
    robot place reject || { echo "PLACE_REJECT_FAIL $s"; exit 1; }
  fi
done
echo "DONE"", "timeout": 600}
